#!/usr/bin/env python3
"""
Fixes the FertiTerra link preview (WhatsApp, Facebook, LinkedIn, X, iMessage).

What was wrong: the card pointed at /images/fertiterra-logo-main.png, which is a
500x500 square lockup (mark + "FertiTerra" + tagline) declared as 1200x630, so
Meta cropped it and showed the old lockup instead of the small red mark.

What this does:
  1. writes public/images/og-fertiterra.png - a 1200x630 card in FertiTerra
     colours (cream #FAF7F2, deep green #1F3D33, red #FF4244 mark, mint accents),
     the tiny red mark top left, the headline in Playfair, and the egg and
     nine-sperm line art bleeding off the right edge
  2. rewrites the title, description, openGraph and twitter blocks in
     app/layout.tsx to point at it

Idempotent. Backs up app/layout.tsx to .bak-before-share-card.
"""
import base64
import re
from pathlib import Path

OG_PNG = base64.b64decode("")

TITLE = "At-Home Fertility & Hormone Tests For Women | FertiTerra"
DESC = (
    "Get clinical-grade fertility and hormone insights, specialist access, "
    "and a personalised care plan. Your reproductive health journey, fully supported."
)

OPENGRAPH = """openGraph: {
    title: "%s",
    description:
      "%s",
    url: "https://fertiterratechnologies.com",
    siteName: "FertiTerra",
    images: [
      {
        url: "/images/og-fertiterra.png",
        width: 1200,
        height: 630,
        alt: "FertiTerra at-home fertility and hormone tests",
      },
    ],
    locale: "en_US",
    type: "website",
  },""" % (TITLE, DESC)

TWITTER = """twitter: {
    card: "summary_large_image",
    title: "%s",
    description:
      "%s",
    images: ["/images/og-fertiterra.png"],
  },""" % (TITLE, DESC)


def replace_object(src, key, new_block):
    """Replace `key: { ... },` using brace matching, not a fixed string."""
    start = src.find(key + ": {")
    if start == -1:
        return src, False
    i = src.index("{", start)
    depth = 0
    for j in range(i, len(src)):
        if src[j] == "{":
            depth += 1
        elif src[j] == "}":
            depth -= 1
            if depth == 0:
                end = j + 1
                if end < len(src) and src[end] == ",":
                    end += 1
                rest = src[end:]
                if not rest.startswith("\n"):
                    rest = "\n" + rest
                return src[:start] + new_block + rest, True
    return src, False


def main():
    if not Path("app").is_dir() or not Path("package.json").is_file():
        print("Run this from the Fertiterra folder.")
        return

    layout = Path("app/layout.tsx")
    if not layout.is_file():
        print("app/layout.tsx not found.")
        return

    img = Path("public/images/og-fertiterra.png")
    img.parent.mkdir(parents=True, exist_ok=True)
    img.write_bytes(OG_PNG)
    print("wrote public/images/og-fertiterra.png (1200x630, %d KB)" % (len(OG_PNG) // 1024))

    src = layout.read_text(encoding="utf-8")
    if 'og-fertiterra.png' in src:
        print("metadata: already points at the new card")
        return

    before = src
    src, ok_og = replace_object(src, "openGraph", OPENGRAPH)
    src, ok_tw = replace_object(src, "twitter", TWITTER)

    if not (ok_og and ok_tw):
        print("metadata: could not find the openGraph/twitter block, nothing changed in layout.tsx")
        print("  openGraph found:", ok_og, " twitter found:", ok_tw)
        return

    # top-level title and description, so the page itself matches the card
    src = re.sub(r'title: "[^"]*",', 'title: "%s",' % TITLE, src, count=1)
    src = re.sub(r'description:\s*\n?\s*"[^"]*",', 'description:\n    "%s",' % DESC, src, count=1)

    layout.with_suffix(".tsx.bak-before-share-card").write_text(before, encoding="utf-8")
    layout.write_text(src, encoding="utf-8")
    print("metadata: title, description, openGraph and twitter rewritten")
    print("  backup: app/layout.tsx.bak-before-share-card")
    print("")
    print("Then restart the dev server: Ctrl+C, then  rm -rf .next && pnpm dev")
    print("")
    print("Meta caches old previews. Force a refresh once you have deployed:")
    print("   https://developers.facebook.com/tools/debug/")
    print("   paste https://fertiterratechnologies.com and press Scrape Again")
    print("   (WhatsApp keeps its own copy for about a week)")


if __name__ == "__main__":
    main()
